command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: MÄUSEMEISTER (Auto-Import, Prozentual, Info-Effekt)
// ==========================================

(async () => {
    let fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Mäusemeister";
    const ahne = "Aphasma"; 
    const finalEffektName = `${gabenName} (${ahne})`;
    const iconBild = DSK_FW.Symbol(ahne);

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qs = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");
    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(casterActor).forEach(id => ownerIds.add(id));

    let targets = Array.from(game.user.targets);
    if (targets.length === 0 || targets.length > 1) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle genau EIN Ziel (Target) für die Verwandlung!");
    }
    const targetToken = targets[0];
    const targetActor = targetToken.actor;
    if (!targetActor) return;

    getOwners(targetActor).forEach(id => ownerIds.add(id));

    // --- ZIEL-PRÜFUNGEN ---
    const zielSpezies = (targetActor.system?.details?.species?.value || targetActor.system?.details?.species || targetActor.system?.species?.value || "").toLowerCase();
    const isErwacht = DSK_FW.Effekt.CheckTarget(targetActor, "erwachte");
    const isTier = DSK_FW.Effekt.CheckTarget(targetActor, "tier") || zielSpezies.includes("tier");

    const zielGroesse = (targetActor.system?.details?.size || targetActor.system?.size || "").toLowerCase();
    const erlaubteGroessen = ["tiny", "small", "average", "winzig", "klein", "mittel"];
    const istGroesseErlaubt = erlaubteGroessen.some(g => zielGroesse.includes(g));

    if (!(isErwacht || isTier) || (!istGroesseErlaubt && zielGroesse !== "")) {
        const failContent = `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="margin-bottom: 8px; text-align: left;"><b>${casterActor.name}</b> versucht <b>${targetActor.name}</b> zu verwandeln...</p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="text-align:center; color:#B30000; font-weight:bold; font-size: 1.1em;">Fehlschlag!</p>
                    <p style="text-align:center; font-size: 0.9em; margin-bottom: 0;">Das Ziel muss ein Tier oder Erwachter der Größe <i>mittel oder kleiner</i> sein.</p>
                </div>
            </div>
        `;
        let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
        if (msg) { await msg.update({ content: failContent, whisper: Array.from(ownerIds) }); } 
        else { await ChatMessage.create({ speaker: { alias: "System" }, whisper: Array.from(ownerIds).filter(id => game.users.get(id)), content: failContent }); }
        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
        return; 
    }

    const dauerMinuten = qs;
    const dauerSekunden = dauerMinuten * 60;
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

    const kompendiumUuid = "Compendium.dsk-core.corebestiary.Actor.BaGVz4HqAZ0QXxsi";
    const mausEintraege = [`@UUID[${kompendiumUuid}]{Maus}`];
    const mausHtml = mausEintraege.map(k => `<li>${k}</li>`).join("");

    // --- AUTO-IMPORT IN DIE WELT ---
    let mausActor = game.actors.getName("Maus");
    if (!mausActor) {
        const compendiumMaus = await fromUuid(kompendiumUuid);
        if (compendiumMaus) {
            mausActor = await Actor.create(compendiumMaus.toObject());
            ui.notifications.info("Luna sagt 🌙: Die Maus wurde automatisch aus dem Kompendium in deine Welt importiert!");
        }
    }

    if (!mausActor) {
        return ui.notifications.warn("Luna sagt 🌙: Konnte die Maus nicht im Kompendium finden!");
    }

    // --- VERWANDLUNG: AUTO-SPAWN & PROZENTUALER STARTWERT ---
    await targetToken.document.update({ hidden: true });

    let td = await mausActor.getTokenDocument();
    let tokenData = td.toObject();
    tokenData.x = targetToken.x;
    tokenData.y = targetToken.y;
    tokenData.hidden = false;
    tokenData.actorLink = false; 

    const tLeP = targetActor.system.stats.LeP;
    const tAeP = targetActor.system.stats.AeP;
    const mMaxLeP = mausActor.system.stats.LeP.max || 1;
    const mMaxAeP = mausActor.system.stats.AeP.max || 1;

    const pctLeP = Math.max(0, Math.min(1, tLeP.value / (tLeP.max || 1)));
    const pctAeP = Math.max(0, Math.min(1, tAeP.value / (tAeP.max || 1)));

    tokenData.delta = {
        system: {
            stats: {
                LeP: { value: Math.max(1, Math.round(mMaxLeP * pctLeP)) },
                AeP: { value: Math.round(mMaxAeP * pctAeP) }
            }
        }
    };

    foundry.utils.setProperty(tokenData, "flags.dsk.isMausVon", targetActor.uuid);
    const spawnedTokens = await canvas.scene.createEmbeddedDocuments("Token", [tokenData]);

    // Info-Effekt auf die beschworene Maus legen
    const spawnedMaus = spawnedTokens[0];
    if (spawnedMaus && spawnedMaus.actor) {
        await spawnedMaus.actor.createEmbeddedDocuments("ActiveEffect", [{
            name: `${finalEffektName} - Verwandlung`,
            icon: iconBild,
            description: `Diese Maus ist in Wahrheit die verwandelte Person ${targetActor.name}.`,
            flags: { core: { statusId: "maeusemeister-wandlung" } }
        }]);
    }

    // --- EFFEKT ANWENDEN ---
    let alterEffekt = targetActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete();

    await targetActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        description: `Das Ziel wurde in eine Maus verwandelt. LeP und AeP sind prozentual mit der Maus verknüpft!`,
        duration: { seconds: dauerSekunden },
        changes: [{ key: "flags.dsk.status", mode: 2, value: "Verwandelt in Maus", priority: 20 }],
        flags: { core: { statusId: "bleeding" }, dsk: { ahne: ahne, hiddenTokenId: targetToken.id } }
    }]);

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("aphasmaMaeusemeister", finalEffektName, "Die Verwandlung endet, die Maus verschwindet und das Ziel nimmt wieder seine wahre Gestalt an.");
    }

    // Lokaler Wächter für sofortigen Live-Sync
    if (!globalThis._dskMaeusemeisterSystem) {
        globalThis._dskMaeusemeisterSystem = true;
        // (Der ausführliche Wächter-Block ist sicher in Lunas Wecker hinterlegt)
    }

    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="margin-bottom: 8px;"><b>${casterActor.name}</b> verwandelt <b>${targetActor.name}</b> in eine Maus.</p>
                <p style="margin-top:0; text-align: left;">Das Ziel behält einen Teil seiner Erinnerungen, übernimmt aber den Körper einer Maus.</p>
                <ul class="dsklist" style="margin-bottom: 8px; text-align: left;">
                    <li><b style="color: #18940F;">Live-Verbindung:</b> Die Maus teilt sich ab sofort ihre Lebens- und Astralpunkte <b style="text-decoration:underline;">prozentual</b> in Echtzeit mit dem Ziel!</li>
                    <li><b>Zielkategorie:</b> Tiere und Erwachte</li>
                    <li><b>Verfügbare Maus:</b><br>${mausHtml}</li>
                </ul>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold; margin-bottom: 0;">
                    Wirkungsdauer:<br>${dauerMinuten} Minuten <span ${thinStyle}>(QS ${qs})</span>
                </p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent, whisper: Array.from(ownerIds) });
    } else {
        await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: Array.from(ownerIds).filter(id => game.users.get(id)),
            content: cardContent
        });
    }
})();
